// 底图：把内置渐变图压暗、偏冷，方便全息层往上叠
uniform sampler2D u_img;
uniform float u_dark;  // @range 0 1 @step 0.01 @default 0.45 @label 压暗

void main() {
  vec3 c = texture(u_img, vUv).rgb;
  c *= mix(1.0, 0.45, u_dark);
  c = mix(c, c * vec3(0.72, 0.92, 1.15), 0.65);
  fragColor = vec4(c, 1.0);
}

// 全息：扫描线 + RGB 错位 + 横向撕裂 + 冷色发光
uniform sampler2D u_src;
uniform float u_lines;    // @range 60 400 @step 10 @default 180 @label 扫描线密度
uniform float u_scan;     // @range 0 1 @step 0.01 @default 0.55 @label 扫描线强度
uniform float u_shift;    // @range 0 0.02 @step 0.0005 @default 0.006 @label 色散
uniform float u_glitch;   // @range 0 1 @step 0.01 @default 0.7 @label 撕裂强度
uniform vec3  u_tint;     // @color @default 0.35 0.95 1 @label 全息色

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
  vec2 uv = vUv;

  // 横向撕裂：按行随机整体平移，随时间跳跃
  float rows = 22.0;
  float row = floor(uv.y * rows);
  float tick = floor(u_time * 7.0);
  float rnd = hash(vec2(row, tick));
  float band = step(0.66, rnd);
  float jitter = (hash(vec2(row, tick + 7.0)) - 0.5) * 0.09 * u_glitch * band;
  uv.x += jitter;

  // 撕裂行整体提亮一点，看起来像信号错位
  float boost = band * u_glitch * 0.35;

  // RGB 错位（边缘更明显）
  float edge = 1.0 - 0.6 * length(vUv - 0.5);
  float sh = u_shift * (0.5 + edge);
  float r = texture(u_src, uv + vec2(sh, 0.0)).r;
  float g = texture(u_src, uv).g;
  float b = texture(u_src, uv - vec2(sh, 0.0)).b;
  vec3 c = vec3(r, g, b);

  // 扫描线
  float line = 0.5 + 0.5 * sin(uv.y * u_lines * 3.14159 + u_time * 4.0);
  c *= 1.0 - u_scan * line * 0.55;

  // 缓慢下移的亮带
  float sweep = fract(u_time * 0.11);
  float bandGlow = smoothstep(0.03, 0.0, abs(uv.y - sweep));
  c += u_tint * bandGlow * 0.22;

  // 全息染色：偏冷，但保留原本的明暗关系
  float lum = dot(c, vec3(0.299, 0.587, 0.114));
  vec3 holo = vec3(lum) * u_tint * 1.5 + c * 0.55;
  c = mix(c, holo, 0.45);
  c += u_tint * boost;

  // 暗角
  vec2 d = uv - 0.5;
  c *= 1.0 - dot(d, d) * 0.6;

  fragColor = vec4(c, 1.0);
}

// 山峦（中间态）：用脊状噪声叠出远近三层山形 + 留白的「雾」
uniform float u_scale;   // @range 0.5 5 @step 0.05 @default 1.6 @label 山形尺度
uniform float u_layers;  // @range 2 5 @step 1 @default 3 @label 层数
uniform float u_mist;    // @range 0 1 @step 0.01 @default 0.45 @label 雾浓度

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// 脊状噪声：1-|2n-1| 会把噪声折成山脊
float ridge(vec2 p) {
  float s = 0.0;
  float amp = 0.55;
  for (int i = 0; i < 4; i++) {
    float n = 1.0 - abs(vnoise(p) * 2.0 - 1.0);
    s += n * n * amp;
    p = p * 2.07 + 11.3;
    amp *= 0.5;
  }
  return s;
}

void main() {
  float aspect = u_resolution.x / max(1.0, u_resolution.y);
  vec2 p = vec2(vUv.x * aspect, vUv.y) * u_scale;
  float t = u_time * 0.02;

  vec3 col = vec3(0.93, 0.92, 0.88);   // 宣纸底
  float ink = 0.0;

  // 由远及近三层：越近颜色越深、山脊越低
  for (int i = 0; i < 3; i++) {
    if (float(i) > u_layers - 1.0) break;
    float k = float(i);
    float depth = 0.32 + k * 0.16;                  // 山脚高度
    float h = ridge(p * (0.8 + k * 0.45) + vec2(t * (0.4 + k * 0.2), k * 5.0));
    float line = smoothstep(depth + 0.30, depth - 0.02, vUv.y + 0.0);
    float body = smoothstep(depth, depth - 0.22, vUv.y) * h;
    ink = max(ink, body * (0.85 - k * 0.22) * line);
  }

  // 雾：把山脚往回淡出去
  float mist = smoothstep(0.0, 0.55, vUv.y) * u_mist;
  ink *= 1.0 - mist;

  col = mix(col, vec3(0.09, 0.10, 0.12), clamp(ink * 1.9, 0.0, 1.0));
  fragColor = vec4(col, 1.0);
}

// 水墨：压成几阶灰 + 纸纹 + 边缘飞白（用亮度梯度当「墨渗」）
uniform sampler2D u_src;
uniform float u_steps;   // @range 2 8 @step 1 @default 4 @label 墨阶
uniform float u_paper;   // @range 0 1 @step 0.01 @default 0.35 @label 纸纹
uniform float u_bleed;   // @range 0 1 @step 0.01 @default 0.4 @label 墨渗

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
  vec3 c = texture(u_src, vUv).rgb;
  float l = dot(c, vec3(0.299, 0.587, 0.114));

  // 阶调
  float n = max(2.0, u_steps);
  float q = floor(l * n + 0.5) / n;

  // 墨渗：用周围亮度差在边缘加一层淡墨，模拟毛边
  vec2 px = 1.6 / u_resolution;
  float lx = dot(texture(u_src, vUv + vec2(px.x, 0.0)).rgb, vec3(0.299, 0.587, 0.114));
  float ly = dot(texture(u_src, vUv + vec2(0.0, px.y)).rgb, vec3(0.299, 0.587, 0.114));
  float edge = clamp((abs(l - lx) + abs(l - ly)) * 6.0, 0.0, 1.0);
  q -= edge * u_bleed * 0.35;

  // 纸纹：低频颗粒 + 一点点纤维
  vec2 gp = vUv * vec2(900.0, 600.0);
  float grain = hash(floor(gp)) * 0.6 + hash(floor(gp * 0.35)) * 0.4;
  q += (grain - 0.5) * 0.09 * u_paper;

  vec3 paper = vec3(0.94, 0.93, 0.89);
  vec3 ink = vec3(0.08, 0.09, 0.11);
  vec3 outCol = mix(paper, ink, clamp(1.0 - q, 0.0, 1.0));

  // 轻微暖边，别太死板
  outCol *= mix(vec3(1.0), vec3(1.02, 0.99, 0.94), 0.6);
  fragColor = vec4(outCol, 1.0);
}

// 底图：轻轻压暗、加一点暖，让后面的火光有地方落
uniform sampler2D u_img;
uniform float u_dark;  // @range 0 1 @step 0.01 @default 0.35 @label 压暗

void main() {
  vec3 c = texture(u_img, vUv).rgb;
  c *= mix(1.0, 0.55, u_dark);
  c = mix(c, c * vec3(1.08, 0.96, 0.86), 0.6);
  fragColor = vec4(c, 1.0);
}

// 火焰（中间态）：不读输入，自己生成一张会向上卷的噪声火
// 输出亮度既当「火苗形状」，也当后面「火焰化」的遮罩
uniform float u_scale;   // @range 1 6 @step 0.05 @default 4.2 @label 火焰尺度
uniform float u_speed;   // @range 0 1.5 @step 0.01 @default 0.45 @label 上升速度
uniform float u_height;  // @range 0.3 1 @step 0.01 @default 0.78 @label 火势高度

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 4; i++) {
    s += vnoise(p) * amp;
    p *= 2.03;
    amp *= 0.5;
  }
  return s;
}

void main() {
  float aspect = u_resolution.x / max(1.0, u_resolution.y);
  vec2 p = vec2(vUv.x * aspect, vUv.y) * u_scale;
  float t = u_time * u_speed;

  // 竖直方向拉长 + 向上滚动：火苗是细长的
  vec2 q = vec2(p.x, p.y * 0.55 - t * 1.4);
  float n1 = fbm(q);
  float n2 = fbm(q * 2.3 + vec2(t * 0.6, -t * 0.3));
  float n = n1 * 0.72 + n2 * 0.42;

  // 越靠下越旺，往上收细
  float rise = smoothstep(0.0, u_height, 1.0 - vUv.y);
  float body = smoothstep(0.45, 0.95, n * (0.55 + rise * 0.75));
  // 再撕几道口子，别让底部糊成一整块
  float breakup = smoothstep(0.18, 0.62, fbm(q * 3.7 + vec2(t * 0.4, -t * 0.9)));
  body *= mix(0.45, 1.0, breakup);
  float core = smoothstep(0.72, 1.0, body) * smoothstep(0.0, 0.55, rise);

  // 亮度即火势；RGB 也顺手给个暖色，方便单独预览这张中间态
  float heat = clamp(body * 0.85 + core * 0.9, 0.0, 1.0);
  vec3 col = mix(vec3(0.05, 0.01, 0.0), vec3(1.0, 0.42, 0.06), body);
  col = mix(col, vec3(1.0, 0.95, 0.72), core);
  fragColor = vec4(col * heat, 1.0);
}

// 火焰化：把第二张图（火焰中间态）的亮度映射成火焰色带，再压回当前画面
uniform sampler2D u_tex;    // 当前画面（上一 Pass）
uniform sampler2D u_layer;  // 火焰中间态
uniform float u_amount;     // @range 0 2 @step 0.01 @default 0.9 @label 强度
uniform float u_gain;       // @range 0.5 3 @step 0.01 @default 1.6 @label 火势放大
uniform float u_cool;       // @range 0 1 @step 0.01 @default 0.15 @label 保留冷色

void main() {
  vec3 base = texture(u_tex, vUv).rgb;
  vec3 fire = texture(u_layer, vUv).rgb;
  float t = clamp(max(fire.r, max(fire.g, fire.b)) * u_gain, 0.0, 1.0);

  // 黑 → 橙红 → 亮黄白的火焰色带
  vec3 ramp = mix(vec3(0.06, 0.01, 0.0), vec3(0.95, 0.28, 0.04), smoothstep(0.0, 0.55, t));
  ramp = mix(ramp, vec3(1.0, 0.93, 0.62), smoothstep(0.55, 1.0, t));

  // 火光把底图烘暖，再用滤色叠上去（不会把底图直接冲成纯白）
  vec3 warm = base * mix(1.0, 0.72, u_cool);
  vec3 glow = ramp * t * u_amount;
  vec3 c = 1.0 - (1.0 - warm) * (1.0 - clamp(glow, 0.0, 1.0));
  fragColor = vec4(c, 1.0);
}

// 星云（中间态）：域扭曲的 fbm，颜色在紫 / 青之间游走
uniform vec3 u_c1;     // @color @default 0.35 0.18 0.85 @label 主色
uniform vec3 u_c2;     // @color @default 0.15 0.75 0.85 @label 副色
uniform float u_scale; // @range 0.5 6 @step 0.05 @default 1.9 @label 尺度
uniform float u_speed; // @range 0 1.5 @step 0.01 @default 0.12 @label 漂流速度

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    s += vnoise(p) * amp;
    p = p * 2.02 + 17.0;
    amp *= 0.5;
  }
  return s;
}

void main() {
  float aspect = u_resolution.x / max(1.0, u_resolution.y);
  vec2 p = vec2(vUv.x * aspect, vUv.y) * u_scale + vec2(u_time * u_speed, 0.0);

  // 域扭曲：先用一层噪声推坐标，再取第二层
  vec2 w = vec2(fbm(p + 3.1), fbm(p + 8.7)) - 0.5;
  float n = fbm(p + w * 1.9);

  // 云的结构：n 靠近 0.5 是稀薄区，两端是浓云
  float dens = smoothstep(0.32, 0.85, n);
  float vein = smoothstep(0.55, 0.95, fbm(p * 2.3 - w));

  vec3 col = mix(vec3(0.01, 0.01, 0.04), u_c1, dens);
  col = mix(col, u_c2, smoothstep(0.45, 0.9, vein) * 0.75);
  col += u_c1 * dens * dens * 0.35;

  fragColor = vec4(col, 1.0);
}

// 星点（中间态）：静态星场 + 少量缓慢闪烁的亮星
uniform float u_count;  // @range 60 600 @step 10 @default 260 @label 星数
uniform float u_size;   // @range 0.05 0.5 @step 0.01 @default 0.22 @label 星点大小
uniform vec3  u_tint;   // @color @default 0.85 0.92 1 @label 星色
uniform float u_twinkle;// @range 0 1 @step 0.01 @default 0.55 @label 闪烁

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
  float aspect = u_resolution.x / max(1.0, u_resolution.y);
  vec2 p = vec2(vUv.x * aspect, vUv.y);
  vec3 col = vec3(0.0);

  // 三层不同密度的网格，避免星点排布规律
  for (int layer = 0; layer < 3; layer++) {
    float cells = u_count * (0.55 + float(layer) * 0.35);
    vec2 g = p * cells;
    vec2 id = floor(g);
    vec2 f = fract(g) - 0.5;

    float rnd = hash(id + float(layer) * 41.7);
    if (rnd > 0.955) {
      vec2 off = vec2(hash(id + 7.1), hash(id + 13.3)) - 0.5;
      float d = length(f - off * 0.7);
      float tw = 0.55 + 0.45 * sin(u_time * (1.2 + rnd * 3.0) + rnd * 20.0);
      float s = smoothstep(u_size, 0.0, d) * mix(1.0, tw, u_twinkle);
      col += u_tint * s * (0.9 + rnd * 1.4);
    }
  }

  fragColor = vec4(col, 1.0);
}

// 滤色叠加：1-(1-A)(1-B)，暗部几乎不变，亮部自然叠亮
uniform sampler2D u_tex;
uniform sampler2D u_layer;
uniform float u_amount;  // @range 0 2 @step 0.01 @default 1.0 @label 强度

void main() {
  vec3 a = texture(u_tex, vUv).rgb;
  vec3 b = texture(u_layer, vUv).rgb * u_amount;
  vec3 c = 1.0 - (1.0 - a) * (1.0 - clamp(b, 0.0, 1.0));
  fragColor = vec4(c, 1.0);
}

// 霓虹网格（中间态）：透视地面网格 + 地平线辉光，纯程序生成
uniform vec3 u_line;    // @color @default 0.35 0.95 1 @label 线色
uniform vec3 u_glow;    // @color @default 0.75 0.25 1 @label 辉光色
uniform float u_cells;  // @range 4 24 @step 1 @default 9 @label 纵列数
uniform float u_speed;  // @range 0 2 @step 0.01 @default 0.55 @label 滚动速度
uniform float u_horizon;// @range 0.3 0.75 @step 0.01 @default 0.52 @label 地平线

void main() {
  float aspect = u_resolution.x / max(1.0, u_resolution.y);
  float hz = u_horizon;

  // 地面：y < 地平线时按透视压缩取深度
  float isGround = step(vUv.y, hz);
  float depth = (hz - vUv.y) / max(1e-3, hz);       // 0 在视线，1 在近处
  float persp = 1.0 / max(0.06, depth);

  // 横向格线（近处线太密会摩尔纹，按深度淡掉）
  float x = (vUv.x - 0.5) * aspect * u_cells * mix(0.4, 3.2, depth);
  float lx = abs(fract(x) - 0.5);
  float nearFade = 1.0 - smoothstep(0.55, 0.95, depth);
  float lineX = smoothstep(0.06, 0.005, lx) * smoothstep(0.0, 0.08, depth) * nearFade;

  // 纵向格线（随深度滚动）
  float z = persp * 0.9 - u_time * u_speed;
  float lz = abs(fract(z) - 0.5);
  float lineZ = smoothstep(0.10, 0.01, lz) * smoothstep(0.0, 0.06, depth) * nearFade;

  float grid = max(lineX, lineZ) * isGround;

  // 地平线上一圈辉光 + 雾气
  float gq = (vUv.y - hz) / 0.055;
  float glowBand = exp(-gq * gq);
  float haze = smoothstep(hz + 0.30, hz - 0.02, vUv.y) * 0.35 * isGround;

  vec3 col = vec3(0.015, 0.01, 0.04);
  col += u_glow * glowBand * 0.32;
  col += u_glow * haze;
  col += u_line * grid * (0.9 + glowBand * 0.7);

  fragColor = vec4(col, 1.0);
}

// 扫描发光：横向扫描线 + 轻微色散 + 亮部扩散（不做多 Pass 也能出「廉价 bloom」）
uniform sampler2D u_src;
uniform float u_scan;   // @range 0 1 @step 0.01 @default 0.35 @label 扫描线
uniform float u_bleed;  // @range 0 1 @step 0.01 @default 0.55 @label 光晕
uniform float u_shift;  // @range 0 0.01 @step 0.0002 @default 0.0016 @label 色散
uniform float u_lines;  // @range 100 900 @step 10 @default 420 @label 线密度

void main() {
  vec2 uv = vUv;
  // 三个通道错开一点点采样，模拟镜头色散
  float cr = texture(u_src, uv + vec2(u_shift, 0.0)).r;
  float cg = texture(u_src, uv).g;
  float cb = texture(u_src, uv - vec2(u_shift, 0.0)).b;
  vec3 c = vec3(cr, cg, cb);

  // 亮部扩散：十字方向取平均，加回去
  vec2 px = 2.0 / u_resolution;
  vec3 blur = texture(u_src, uv + vec2(px.x, 0.0)).rgb
            + texture(u_src, uv - vec2(px.x, 0.0)).rgb
            + texture(u_src, uv + vec2(0.0, px.y)).rgb
            + texture(u_src, uv - vec2(0.0, px.y)).rgb;
  blur *= 0.25;
  c += blur * u_bleed;

  // 扫描线
  float line = 0.5 + 0.5 * sin(vUv.y * u_lines * 3.14159 + u_time * 2.4);
  c *= 1.0 - u_scan * line * 0.45;

  // 很轻的暗角，让中心亮一点
  vec2 d = uv - 0.5;
  c *= 1.0 - dot(d, d) * 0.55;

  fragColor = vec4(c, 1.0);
}
